---@class ActivityMidFestivalTaskTool
local ActivityMidFestivalTaskTool = {}

function ActivityMidFestivalTaskTool.TaskReq()
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local activityId = activityComp:GetActivityDojo().id
    ---@type MidFestivalTaskDojo
    local taskDojo = activityComp:GetTaskDojo()

    GameUtils.Request(Interfaces.OverseaMidFestivalTask, {activityUuid = activityId, type = 1 }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        
         taskDojo:Fill(jsonData)
        Events.Broadcast(Constants.EventNames.ActivityMidFestivalTaskReq)
    end)
end


return ActivityMidFestivalTaskTool
